INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','easy','mcq','Which two hormone types are combined in the combined oral contraceptive pill (COCP)?','["A. Oestrogen and progestogen", "B. Oestrogen and androgen", "C. Progestogen and androgen", "D. Oestrogen and glucocorticoid"]','A','The COCP contains synthetic oestrogen (usually ethinylestradiol) and a synthetic progestogen. Together they suppress the LH surge, preventing ovulation. This combination also thickens cervical mucus and alters the endometrium.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','easy','mcq','What is the primary mechanism by which the COCP prevents pregnancy?','["A. Suppression of ovulation via inhibition of the LH surge", "B. Prevention of implantation by thinning the endometrium", "C. Inhibition of fertilisation by thickening cervical mucus", "D. Spermicidal effect of synthetic oestrogen"]','A','The dominant contraceptive mechanism of the COCP is suppression of the midcycle LH surge, thereby preventing ovulation. Secondary mechanisms include cervical mucus thickening and endometrial atrophy, but suppression of ovulation is primary.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','medium','mcq','A 28-year-old woman taking the COCP is commenced on rifampicin for tuberculosis. What is the most important concern?','["A. Reduced contraceptive efficacy due to enzyme induction", "B. Risk of hepatotoxicity from drug combination", "C. Increased risk of venous thromboembolism", "D. Rifampicin inhibits oestrogen absorption"]','A','Rifampicin is a potent inducer of CYP450 enzymes (particularly CYP3A4), accelerating the metabolism of ethinylestradiol and progestogen. This substantially reduces plasma levels and contraceptive efficacy, risking unintended pregnancy. Additional contraception is required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','medium','mcq','Which of the following is a non-contraceptive benefit of the combined oral contraceptive pill?','["A. Reduced risk of ovarian cancer", "B. Reduced risk of cervical cancer", "C. Increased bone mineral density after menopause", "D. Reduced risk of breast cancer"]','A','The COCP is associated with a reduced risk of ovarian and endometrial cancers, likely due to suppression of ovulation and endometrial proliferation. It is associated with a small increased risk of cervical and breast cancers, not a reduction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','medium','mcq','A 35-year-old woman who smokes 20 cigarettes per day requests the COCP. What is the main reason it is contraindicated?','["A. Smoking combined with oestrogen significantly increases VTE and arterial thrombosis risk", "B. Smoking reduces oestrogen levels below therapeutic range", "C. Nicotine is a CYP3A4 inducer that reduces COCP efficacy", "D. Smoking increases progestogen metabolism"]','A','Smoking combined with oestrogen-containing contraceptives markedly increases the risk of venous thromboembolism (VTE), stroke, and myocardial infarction, particularly in women over 35. This is an absolute contraindication (UKMEC 4) in women over 35 who smoke.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','hard','mcq','Which progestogen in the COCP has the highest androgenic activity and is most associated with acne and hirsutism?','["A. Norethisterone", "B. Desogestrel", "C. Drospirenone", "D. Gestodene"]','A','Norethisterone (and levonorgestrel) are older progestogens with significant androgenic activity, which can cause acne, hirsutism, and unfavourable lipid changes. Desogestrel, gestodene, and drospirenone are third/fourth-generation progestogens with lower androgenic activity; drospirenone has anti-androgenic properties.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','hard','mcq','A woman on the COCP develops a DVT. Analysis shows she is heterozygous for Factor V Leiden mutation. Which statement is most accurate?','["A. Factor V Leiden causes resistance to activated protein C, and oestrogen further increases this risk synergistically", "B. Factor V Leiden alone carries minimal VTE risk; oestrogen was the main cause", "C. The COCP is safe in Factor V Leiden carriers if progestogen-only pills are used instead", "D. Warfarin should be started and the COCP continued with additional thromboprophylaxis"]','A','Factor V Leiden mutation confers resistance to activated protein C (APC), increasing VTE risk 5-8-fold. Oestrogen in the COCP further promotes a pro-coagulant state by increasing clotting factors and reducing protein S. The combination is synergistic, increasing VTE risk 30-50-fold compared to non-users without the mutation. The COCP is absolutely contraindicated in known thrombophilias.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','easy','mcq','The oestrogen component of most combined oral contraceptive pills is which of the following?','["A. Ethinylestradiol", "B. Conjugated equine oestrogen", "C. Estradiol valerate", "D. Estriol"]','A','Ethinylestradiol is the synthetic oestrogen used in the majority of COCPs. It has high oral bioavailability due to the ethinyl group at C17, which prevents first-pass hepatic metabolism. Estradiol valerate is used in some newer preparations (e.g., Qlaira).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','medium','mcq','Which of the following conditions is an absolute contraindication (UKMEC 4) to the use of combined oral contraceptives?','["A. Personal history of venous thromboembolism", "B. Migraine without aura", "C. Age over 40 years", "D. Well-controlled hypertension with BP 140/90 mmHg"]','A','A personal history of VTE is an absolute contraindication to oestrogen-containing contraceptives due to the significantly increased risk of recurrent thrombosis. Migraine without aura is UKMEC 2, well-controlled hypertension may be UKMEC 2-3, and age alone is not an absolute contraindication.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Combined Oral Contraceptives','hard','mcq','A woman takes the COCP and develops breakthrough bleeding in month 3. She has not missed any pills and takes no other medication. What is the most likely explanation?','["A. Transient endometrial atrophy from prolonged progestogen effect causing irregular shedding", "B. She is likely pregnant", "C. The pill has stopped working and she needs emergency contraception", "D. Ethinylestradiol dose is too high, causing endometrial hyperplasia"]','A','Breakthrough bleeding in COCP users is most commonly caused by endometrial atrophy from sustained progestogen dominance, leading to irregular shedding of the atrophic endometrium. It is not indicative of contraceptive failure per se and often settles after 3 months. A higher-oestrogen preparation or switching progestogen type may help.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','easy','mcq','Which of the following statements about the progestogen-only pill (POP) is correct?','["A. The desogestrel POP (Cerazette) reliably suppresses ovulation", "B. It contains ethinylestradiol as the active component", "C. It is contraindicated in breastfeeding women", "D. It must be taken within 2 hours of the same time each day"]','A','The desogestrel 75 mcg POP (Cerazette) reliably suppresses ovulation in ~97% of cycles, unlike older POPs (e.g., norethisterone) which primarily work by thickening cervical mucus. The desogestrel POP has a 12-hour window for missed pills, is safe in breastfeeding, and contains no oestrogen.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','easy','mcq','Levonorgestrel emergency contraception (e.g., Plan B) is most effective when taken within what time frame after unprotected intercourse?','["A. 72 hours", "B. 24 hours", "C. 120 hours", "D. 7 days"]','A','Levonorgestrel emergency contraception is most effective when taken within 72 hours (3 days) of unprotected sexual intercourse, with efficacy decreasing with time. Ulipristal acetate is licensed up to 120 hours (5 days). The copper IUD can be used up to 5 days after.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','medium','mcq','A woman takes ulipristal acetate (ellaOne) as emergency contraception. She is also on the combined oral contraceptive pill. What advice should she be given?','["A. Ulipristal may reduce the efficacy of hormonal contraception and vice versa; use barrier methods for 5 days after", "B. Use condoms for 14 days after taking ulipristal and restart COCP immediately", "C. No additional precautions needed \u2014 the COCP provides backup protection", "D. Stop the COCP permanently and switch to the copper IUD"]','A','Ulipristal acetate is a selective progesterone receptor modulator. Hormonal contraceptives (containing progestogens) may reduce ulipristal''s efficacy, and ulipristal may reduce the efficacy of ongoing hormonal contraception. Women should use barrier methods for at least 5 days after taking ulipristal.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','medium','mcq','What is the primary mechanism of action of levonorgestrel when used as emergency contraception?','["A. Inhibition or delay of ovulation", "B. Prevention of implantation of the fertilised egg", "C. Luteolytic effect on the corpus luteum", "D. Spermicidal action in the cervical canal"]','A','The primary mechanism of levonorgestrel emergency contraception is inhibition or delay of ovulation. It is ineffective once ovulation has occurred. It does not reliably prevent implantation, and evidence for this mechanism in clinical doses is lacking. There is no spermicidal or luteolytic effect.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','medium','mcq','A 60 kg woman requests levonorgestrel emergency contraception 48 hours after unprotected intercourse. She weighs 90 kg. What is the most appropriate advice?','["A. Copper IUD insertion is preferred given reduced levonorgestrel efficacy at her weight, but ulipristal is an alternative", "B. Double the dose to 3 mg levonorgestrel due to reduced efficacy in women over 70 kg", "C. Levonorgestrel is contraindicated in obesity; use ulipristal instead", "D. Standard dose 1.5 mg is fully effective regardless of body weight"]','A','Evidence suggests levonorgestrel emergency contraception may be less effective in women over 70-75 kg, with significantly reduced efficacy at 90 kg. Ulipristal acetate appears more effective at higher body weights. The copper IUD remains the most effective emergency contraceptive regardless of weight.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','hard','mcq','Which statement best distinguishes the mechanism of ulipristal acetate from levonorgestrel for emergency contraception?','["A. Ulipristal can inhibit or delay ovulation even after the LH surge has begun; levonorgestrel is only effective before the LH surge", "B. Ulipristal works by preventing implantation; levonorgestrel prevents fertilisation", "C. Ulipristal is a progestogen receptor agonist; levonorgestrel is an antagonist", "D. There is no mechanistic difference; ulipristal is simply a higher dose of levonorgestrel"]','A','Ulipristal acetate is a selective progesterone receptor modulator (SPRM) that can inhibit follicular rupture even after the LH surge has started, explaining its superior efficacy at 72-120 hours. Levonorgestrel is only effective if taken before the LH surge; once ovulation is imminent, it is ineffective.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','easy','mcq','The progestogen-only pill is a preferred contraceptive choice in which of the following groups?','["A. Breastfeeding women, women with migraine with aura, or women with VTE history", "B. Women with a history of ectopic pregnancy only", "C. Women who desire regular withdrawal bleeds", "D. Perimenopausal women wishing to reduce hot flushes"]','A','The POP is oestrogen-free and therefore suitable for women in whom oestrogen is contraindicated: breastfeeding mothers, women with migraine with aura, hypertension, VTE history, or cardiovascular risk factors. It does not suppress withdrawal bleeds reliably; irregular bleeding is a common side effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','hard','mcq','A woman on the desogestrel POP (Cerazette) is started on St John''s Wort by her naturopath. What is the clinical concern?','["A. St John''s Wort is a CYP3A4 inducer and reduces desogestrel efficacy, risking contraceptive failure", "B. St John''s Wort is a CYP3A4 inhibitor and increases desogestrel levels, causing VTE", "C. There is no clinically significant interaction between herbal remedies and the POP", "D. St John''s Wort reduces enterohepatic recirculation of desogestrel"]','A','St John''s Wort (Hypericum perforatum) is a potent inducer of CYP3A4 and P-glycoprotein. This accelerates the metabolism of desogestrel, substantially reducing plasma levels and contraceptive efficacy. Women should be counselled to avoid St John''s Wort with any hormonal contraceptive.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','medium','mcq','A traditional norethisterone POP is missed for 4 hours past the usual time. What action is required?','["A. Take the missed pill immediately and use barrier contraception for 48 hours", "B. No action needed \u2014 the pill has a 12-hour window", "C. Take the missed pill immediately and use barrier contraception for 7 days", "D. Emergency contraception is required immediately"]','A','Traditional POPs (e.g., norethisterone) have a 3-hour window; if taken more than 3 hours late, the pill is considered missed. The missed pill should be taken immediately, and additional barrier contraception should be used for the next 48 hours. The desogestrel POP has a more forgiving 12-hour window.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Progestogen-Only and Emergency Contraception','hard','mcq','A woman asks about the mechanism of the levonorgestrel-releasing intrauterine system (LNG-IUS, Mirena). Which best describes how it prevents pregnancy?','["A. Local progestogenic effect thickening cervical mucus and thinning the endometrium, with minimal systemic absorption", "B. Releases high systemic levels of levonorgestrel that suppress ovulation reliably", "C. Creates a cytotoxic environment that kills sperm in the uterus", "D. Creates a physical barrier preventing sperm from reaching the fallopian tubes"]','A','The LNG-IUS works primarily locally: high intrauterine concentrations of levonorgestrel thicken cervical mucus and cause endometrial atrophy, preventing sperm penetration and implantation. Systemic absorption is low and ovulation is suppressed in only ~25% of cycles. It is not a purely physical device.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','easy','mcq','Oxytocin is used to induce labour. What is its primary mechanism of action?','["A. Binds to myometrial oxytocin receptors, increasing intracellular calcium and causing uterine contractions", "B. Inhibits prostaglandin synthesis, reducing uterine pain", "C. Blocks progesterone receptors, removing progesterone-mediated uterine quiescence", "D. Stimulates beta-2 adrenoceptors in the myometrium"]','A','Oxytocin binds to Gq-coupled oxytocin receptors on myometrial cells, activating phospholipase C and increasing intracellular calcium, triggering uterine contractions. Receptor density increases markedly during late pregnancy and labour, enhancing sensitivity to oxytocin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','easy','mcq','Ergometrine is used in the management of postpartum haemorrhage (PPH). What is its mechanism of action?','["A. Alpha-adrenoceptor and serotonin receptor agonist causing sustained uterine tetanic contraction", "B. Oxytocin receptor agonist causing rhythmic uterine contractions", "C. Prostaglandin E2 analogue causing cervical ripening", "D. Selective beta-2 agonist relaxing the uterus"]','A','Ergometrine is an ergot alkaloid that stimulates alpha-adrenoceptors and serotonin (5-HT2) receptors in uterine smooth muscle, producing prolonged, sustained (tetanic) contractions. This sustained contraction mechanically compresses uterine blood vessels, reducing haemorrhage.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','medium','mcq','A woman with pre-eclampsia develops PPH. Why should ergometrine be used with caution or avoided?','["A. Ergometrine causes vasoconstriction and can precipitate severe hypertension", "B. Ergometrine causes uterine atony in hypertensive patients", "C. Ergometrine causes hypotension when used in women with pre-eclampsia", "D. Ergometrine is teratogenic and should be avoided postpartum"]','A','Ergometrine causes systemic vasoconstriction via alpha-adrenoceptor stimulation, which can precipitate or worsen severe hypertension. In women with pre-eclampsia or hypertension, this is potentially life-threatening. Oxytocin alone is preferred in hypertensive patients. Syntometrine (oxytocin + ergometrine) is avoided in hypertension.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','medium','mcq','Misoprostol is used as a uterotonic agent. What class of drug is it?','["A. Prostaglandin E1 analogue", "B. Oxytocin analogue", "C. Ergot alkaloid", "D. Prostaglandin E2 analogue"]','A','Misoprostol is a synthetic prostaglandin E1 (PGE1) analogue. It was originally developed for peptic ulcer disease but is used in obstetrics for cervical ripening, induction of labour, medical abortion, and PPH management. It is heat-stable and can be given orally, sublingually, or rectally — an advantage in resource-limited settings.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','medium','mcq','A woman receives IV oxytocin infusion for induction of labour but develops polyhydramnios-like signs and drowsiness. Blood sodium is 125 mmol/L. What complication has occurred?','["A. Hypernatraemia from IV fluid overload","B. Water intoxication and hyponatraemia due to oxytocin''s antidiuretic (ADH-like) effect","C. Oxytocin toxicity causing sodium wasting nephropathy","D. Dilutional hyponatraemia from excessive 5% dextrose administration unrelated to oxytocin"]','B','Oxytocin has structural similarity to ADH (antidiuretic hormone) and can exert antidiuretic effects, particularly at high doses. This causes water retention, resulting in dilutional hyponatraemia with symptoms of water intoxication: headache, nausea, confusion, and seizures in severe cases.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','hard','mcq','Carboprost (15-methyl PGF2-alpha) is used for PPH refractory to oxytocin and ergometrine. In which patient is it contraindicated?','["A. Patients with previous caesarean section","B. Patients with asthma","C. Patients with pre-eclampsia","D. Patients with type 1 diabetes"]','B','Carboprost is a prostaglandin F2-alpha analogue that causes potent bronchoconstriction via FP receptor activation. It is absolutely contraindicated in women with asthma as it can precipitate life-threatening bronchospasm. In an asthmatic patient with refractory PPH, misoprostol or a B-Lynch suture may be used instead.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','hard','mcq','Dinoprostone (PGE2) is used for cervical ripening prior to induction of labour. What is the main risk requiring continuous fetal monitoring?','["A. Maternal hypotension from systemic vasodilation","B. Uterine hyperstimulation leading to fetal distress","C. Maternal bronchospasm and anaphylaxis","D. Prolongation of the QT interval"]','B','Dinoprostone (PGE2) can cause uterine hyperstimulation — excessive uterine contractions (tachysystole) that reduce uteroplacental blood flow, causing fetal hypoxia and distress. Continuous electronic fetal monitoring (CTG) is required. If hyperstimulation occurs, the vaginal insert can be removed and tocolytics (e.g., terbutaline) administered.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','easy','mcq','Syntometrine is a combined preparation used in active management of the third stage of labour. What does it contain?','["A. Oxytocin and misoprostol","B. Oxytocin and ergometrine","C. Misoprostol and dinoprostone","D. Ergometrine and carboprost"]','B','Syntometrine is a fixed-dose combination of oxytocin (5 units) and ergometrine (500 micrograms) given by intramuscular injection for active management of the third stage of labour to prevent PPH. It combines the rapid onset of oxytocin with the sustained action of ergometrine but is avoided in hypertension.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','hard','mcq','Tranexamic acid is now recommended in PPH management. What is its mechanism of action?','["A. Stimulates uterine contractions by binding oxytocin receptors","B. Inhibits fibrinolysis by competitively blocking lysine binding sites on plasminogen","C. Activates factor X in the extrinsic coagulation pathway","D. Inhibits thromboxane A2 synthesis, reducing platelet aggregation"]','B','Tranexamic acid is an antifibrinolytic agent that competitively inhibits the binding of plasminogen to fibrin by blocking lysine binding sites. This prevents plasminogen activation to plasmin, preserving the clot. The WOMAN trial showed it significantly reduces PPH mortality when given within 3 hours of delivery.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Oxytocics and Uterotonics','medium','mcq','What is the route of administration of oxytocin for induction of labour?','["A. Intramuscular injection", "B. Intravenous infusion (titrated)", "C. Oral tablet", "D. Sublingual tablet"]','B','Oxytocin for induction of labour is administered as an intravenous infusion, carefully titrated to achieve regular contractions (3 contractions per 10 minutes). This allows precise dose control and rapid cessation if hyperstimulation or fetal distress occurs. Oral oxytocin is poorly bioavailable due to hepatic first-pass metabolism.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','easy','mcq','Which drug class is nifedipine, and how does it act as a tocolytic?','["A. Beta-2 agonist — relaxes uterine smooth muscle by increasing cAMP","B. Calcium channel blocker — reduces intracellular calcium in myometrial cells, inhibiting contractions","C. Oxytocin receptor antagonist — blocks oxytocin-mediated uterine contractions","D. Prostaglandin synthetase inhibitor — reduces prostaglandin-driven contractions"]','B','Nifedipine is a dihydropyridine calcium channel blocker. It reduces intracellular calcium influx in myometrial smooth muscle cells, decreasing contractility. It is widely used as a first-line tocolytic for preterm labour, with good evidence and a favourable side-effect profile compared to beta-agonists.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','easy','mcq','Atosiban is a tocolytic agent used to suppress preterm labour. What is its mechanism of action?','["A. Calcium channel blockade in myometrial cells", "B. Competitive antagonism of oxytocin and vasopressin V1a receptors", "C. Beta-2 adrenoceptor agonism in uterine smooth muscle", "D. Inhibition of cyclooxygenase, reducing prostaglandin synthesis"]','B','Atosiban is a competitive antagonist at oxytocin receptors and vasopressin V1a receptors. By blocking oxytocin-mediated signalling, it reduces myometrial contractility. It has fewer cardiovascular side effects than beta-agonists and is the preferred tocolytic in Europe for preterm labour between 24-33 weeks.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','medium','mcq','A woman in preterm labour at 28 weeks is given salbutamol (ritodrine) as a tocolytic. She develops palpitations and chest pain. What is the most likely cause?','["A. Atrial fibrillation due to magnesium depletion","B. Beta-2 mediated tachycardia and cardiac stimulation causing maternal cardiomyopathy risk","C. Uterotonic effect causing reduced cardiac output","D. Hypoglycaemia-induced arrhythmia"]','B','Beta-2 agonists (salbutamol, ritodrine, terbutaline) cause maternal side effects including tachycardia, palpitations, chest pain, and pulmonary oedema, particularly with prolonged IV use. Beta-2 receptors are not entirely selective — beta-1 cardiac stimulation also occurs. Rare but serious cases of maternal cardiomyopathy have been reported.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','medium','mcq','Tocolytics are used for preterm labour primarily to achieve which goal?','["A. Permanently arrest preterm labour and allow pregnancy to continue to 40 weeks","B. Delay delivery by 24-48 hours to allow corticosteroids to promote fetal lung maturity","C. Reduce fetal pain during contractions","D. Prevent recurrence of preterm labour in subsequent pregnancies"]','B','The primary goal of tocolysis is to delay delivery by 24-48 hours, allowing time for maternal administration of corticosteroids (betamethasone or dexamethasone) to accelerate fetal lung surfactant production and reduce the risk of respiratory distress syndrome. Tocolytics do not significantly prolong pregnancy beyond this window.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','hard','mcq','A woman at 30 weeks gestation is given indomethacin as a tocolytic. What fetal risk is associated with this drug particularly after 32 weeks?','["A. Fetal renal tubular dysgenesis causing oligohydramnios","B. Premature closure of the ductus arteriosus","C. Fetal adrenal suppression from COX-2 inhibition","D. Fetal intracerebral haemorrhage"]','B','Indomethacin (a non-selective COX inhibitor) is used as a tocolytic before 32 weeks. Prostaglandins maintain ductus arteriosus patency; inhibiting COX reduces prostaglandin synthesis and can cause premature ductus arteriosus constriction, leading to pulmonary hypertension in the neonate. This risk increases significantly after 32 weeks, limiting its use to earlier gestations.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','hard','mcq','Which tocolytic has the most evidence for neonatal neuroprotection in addition to delaying preterm labour?','["A. Nifedipine", "B. Magnesium sulphate", "C. Atosiban", "D. Indomethacin"]','B','Magnesium sulphate, when given to women at risk of preterm birth before 32 weeks, reduces the risk of cerebral palsy and major motor dysfunction in surviving preterm neonates. This is a neuroprotective benefit independent of its tocolytic effect. It is recommended in NICE and international guidelines for this indication.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','medium','mcq','Which metabolic complication can occur in the fetus/neonate when beta-2 agonist tocolytics are used in the mother?','["A. Hyperkalaemia", "B. Neonatal hypoglycaemia", "C. Metabolic acidosis", "D. Hypocalcaemia"]','B','Beta-2 agonists cause maternal hyperglycaemia by stimulating glycogenolysis and gluconeogenesis. Fetal hyperglycaemia follows via placental transfer. After delivery, the neonate''s beta cells continue producing high insulin against a falling glucose supply, causing neonatal hypoglycaemia. Monitoring neonatal blood glucose is important.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','easy','mcq','Corticosteroids (betamethasone) are given to women in preterm labour. What is their purpose?','["A. To reduce maternal inflammatory response and treat chorioamnionitis","B. To accelerate fetal lung maturity and surfactant production","C. To inhibit uterine contractions via glucocorticoid receptors","D. To prevent maternal postpartum haemorrhage"]','B','Antenatal corticosteroids (betamethasone 12 mg IM x2 doses 24 hours apart, or dexamethasone) are given between 24-34 weeks to accelerate fetal lung maturation. They induce surfactant synthesis in type II pneumocytes, reducing the incidence and severity of neonatal respiratory distress syndrome (RDS).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','hard','mcq','A nifedipine-treated woman in preterm labour also requires magnesium sulphate for neuroprotection. What interaction should be monitored?','["A. Nifedipine and magnesium have antagonistic effects and reduce tocolytic efficacy when combined","B. The combination may cause potentiation of neuromuscular blockade and severe hypotension","C. Magnesium increases nifedipine metabolism, reducing plasma levels","D. The combination causes hypermagnesaemia-induced VT"]','B','Both nifedipine (calcium channel blocker) and magnesium sulphate (physiological calcium antagonist) inhibit calcium-dependent processes. Their combination can potentiate neuromuscular blockade and cardiovascular depression, causing severe hypotension and neuromuscular weakness. Clinical monitoring of maternal reflexes, respiratory rate, and blood pressure is essential.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','easy','mcq','Which folic acid dose is recommended preconceptually and in the first trimester to reduce the risk of neural tube defects?','["A. 400 micrograms daily", "B. 400 micrograms daily for standard-risk women and 5 mg daily for high-risk women", "C. 5 mg daily for standard-risk women", "D. 1 mg daily"]','B','Standard-risk women (no prior NTD pregnancy, not on antiepileptics, not obese) should take 400 mcg (0.4 mg) folic acid daily from preconception to 12 weeks. High-risk women (prior NTD pregnancy, taking valproate/carbamazepine, BMI >30, diabetes, coeliac disease) should take 5 mg daily.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','easy','mcq','Thalidomide was withdrawn from use in pregnant women due to which teratogenic effect?','["A. Neural tube defects (spina bifida)","B. Limb reduction defects (phocomelia)","C. Cardiac septal defects","D. Cleft palate and lip"]','B','Thalidomide, used as an antiemetic in the 1950s-60s, caused phocomelia (severe limb reduction defects — flipper-like limbs) and other abnormalities when taken during the critical period of limb development (days 20-36 post-conception). This led to strict thalidomide teratogenicity regulations and is the classic example of drug-induced teratogenicity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','medium','mcq','An epileptic woman on sodium valproate becomes pregnant. What is the main fetal risk from valproate?','["A. Neonatal hypoglycaemia","B. Neural tube defects, cardiac defects, and neurodevelopmental delay (fetal valproate syndrome)","C. Neonatal thyroid suppression","D. Neonatal bleeding due to vitamin K deficiency"]','B','Sodium valproate is highly teratogenic. Fetal valproate syndrome includes neural tube defects (spina bifida — 1-2% risk), cardiac malformations, facial dysmorphism, and long-term neurodevelopmental impairment (reduced IQ, autism spectrum disorder). The risk is dose-dependent. Women of childbearing age must be enrolled in a Pregnancy Prevention Programme.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','medium','mcq','ACE inhibitors are contraindicated in pregnancy, particularly in the second and third trimesters. What fetal complications can they cause?','["A. Macrosomia and fetal overgrowth","B. Renal dysgenesis, oligohydramnios, and hypocalvaria (ACE inhibitor fetopathy)","C. Intracerebral haemorrhage","D. Cardiac arrhythmias and heart block"]','B','ACE inhibitors in the second and third trimesters reduce fetal renal blood flow, impairing kidney development (renal dysgenesis/tubular dysgenesis) and causing oligohydramnios (lack of amniotic fluid). Reduced amniotic fluid causes pulmonary hypoplasia, limb contractures, and hypocalvaria (underdeveloped skull bones). First trimester ACE inhibitor use is less clearly teratogenic.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','medium','mcq','Which antibiotic is considered safe to use in pregnancy throughout all trimesters?','["A. Tetracycline", "B. Amoxicillin", "C. Trimethoprim", "D. Ciprofloxacin"]','B','Amoxicillin (and other penicillins) are considered safe throughout pregnancy and are commonly used for UTIs, dental infections, and other bacterial infections in pregnant women. Tetracyclines cause tooth discolouration and inhibit bone growth. Trimethoprim is a folate antagonist (avoid in first trimester). Fluoroquinolones may affect cartilage development.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','hard','mcq','Warfarin is associated with specific fetal risks in the first trimester. What is the classic syndrome?','["A. DiGeorge syndrome","B. Warfarin embryopathy — nasal hypoplasia, stippled epiphyses, ophthalmic abnormalities","C. Ebstein anomaly of the tricuspid valve","D. Pierre Robin sequence with micrognathia"]','B','Warfarin crosses the placenta and, in the first trimester (weeks 6-12), inhibits vitamin K-dependent gamma-carboxylation of proteins including osteocalcin, causing warfarin embryopathy: nasal hypoplasia (saddle nose), stippled epiphyses on radiograph, and ocular abnormalities. In the second/third trimesters, it causes fetal intracranial haemorrhage. Heparin (does not cross placenta) is preferred.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','hard','mcq','A woman with systemic lupus erythematosus (SLE) is pregnant and requires hydroxychloroquine. What is the correct advice?','["A. Hydroxychloroquine must be stopped immediately as it causes fetal ocular toxicity","B. Hydroxychloroquine should be continued — stopping increases risk of SLE flare, and it is considered safe in pregnancy","C. Switch to methotrexate for better disease control during pregnancy","D. Dose should be halved during pregnancy to reduce fetal exposure"]','B','Hydroxychloroquine is considered safe in pregnancy and is one of the few disease-modifying drugs that can be continued. Stopping it risks SLE flare, which poses greater maternal and fetal risk than the drug itself. Methotrexate is absolutely contraindicated in pregnancy (major teratogen and abortifacient).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','easy','mcq','Which analgesic should be avoided in the third trimester of pregnancy due to risk of premature closure of the ductus arteriosus?','["A. Paracetamol", "B. Ibuprofen (NSAIDs)", "C. Codeine", "D. Morphine"]','B','NSAIDs (e.g., ibuprofen, diclofenac) inhibit prostaglandin synthesis. In the third trimester, prostaglandins maintain ductus arteriosus patency. NSAID use can cause premature ductal constriction, leading to neonatal pulmonary hypertension. NSAIDs are also associated with oligohydramnios and renal impairment. Paracetamol remains the analgesic of choice throughout pregnancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','hard','mcq','A pregnant woman with bipolar disorder is on lithium. Which fetal cardiac malformation is associated with first-trimester lithium exposure?','["A. Ventricular septal defect","B. Ebstein anomaly of the tricuspid valve","C. Hypoplastic left heart syndrome","D. Transposition of the great vessels"]','B','First-trimester lithium exposure is associated with Ebstein anomaly — a rare congenital malformation of the tricuspid valve where the valve is displaced apically into the right ventricle. The absolute risk is small but elevated compared to background. Lithium should ideally be avoided in the first trimester or the dose kept as low as possible.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs in Pregnancy','medium','mcq','Low-dose aspirin (75-150 mg/day) is recommended in pregnancy for which indication?','["A. Prevention of gestational diabetes", "B. Prevention of pre-eclampsia in high-risk women", "C. Treatment of mild pre-eclampsia", "D. Analgesia in the second trimester"]','B','Low-dose aspirin reduces the risk of pre-eclampsia in high-risk women (previous pre-eclampsia, chronic hypertension, diabetes, multifetal pregnancy, renal disease) when started before 16 weeks. It inhibits thromboxane A2 more than prostacyclin, improving uteroplacental blood flow and reducing platelet aggregation in the placental vasculature.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','easy','mcq','What is the drug of choice for acute severe hypertension (BP ≥ 160/110 mmHg) in a woman with pre-eclampsia in the UK?','["A. Amlodipine", "B. Enalapril", "C. Labetalol IV or oral", "D. Atenolol"]','C','Labetalol (oral or IV) is the first-line antihypertensive for acute hypertension in pre-eclampsia in the UK. It is a combined alpha and beta blocker that reduces peripheral vascular resistance and heart rate. IV labetalol is used for rapid control. ACE inhibitors are contraindicated in pregnancy. Atenolol is associated with fetal growth restriction.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','easy','mcq','Magnesium sulphate is used in pre-eclampsia. What is its primary clinical role?','["A. Antihypertensive to control blood pressure","B. Diuretic to reduce oedema","C. Prevention and treatment of eclamptic seizures","D. Tocolytic to prevent preterm labour"]','C','Magnesium sulphate is used for seizure prophylaxis (primary prevention of eclampsia in women with severe pre-eclampsia) and treatment of eclamptic convulsions. The Magpie Trial showed a 58% relative risk reduction in eclampsia with magnesium sulphate. It is not primarily an antihypertensive in this context.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','medium','mcq','A woman receiving magnesium sulphate for eclampsia prophylaxis develops absent deep tendon reflexes and her respiratory rate is 8/min. What is the immediate treatment?','["A. Increase the magnesium sulphate infusion rate", "B. Give IV diazepam to manage expected seizure", "C. Stop magnesium sulphate and give IV calcium gluconate", "D. Administer IV furosemide to enhance magnesium excretion"]','C','Signs of magnesium toxicity include loss of deep tendon reflexes (earliest sign, at ~5-7 mmol/L), respiratory depression (at ~7-10 mmol/L), and cardiac arrest (>12 mmol/L). The antidote is IV calcium gluconate (10 mL of 10% solution), which competes with magnesium. The infusion must be stopped immediately.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','medium','mcq','Nifedipine modified-release is used as an antihypertensive in pre-eclampsia. Which adverse effect should be monitored when used alongside magnesium sulphate?','["A. Hypertensive crisis from synergistic vasoconstriction", "B. Magnesium accelerates nifedipine metabolism, reducing efficacy", "C. Potentiation of neuromuscular blockade and severe hypotension", "D. Risk of pulmonary oedema from combined volume expansion"]','C','Both nifedipine (calcium channel blocker) and magnesium sulphate (physiological calcium antagonist) inhibit calcium-mediated processes. Their combination can cause potentiation of neuromuscular blockade, excessive vasodilation, and severe hypotension. Close monitoring of blood pressure and neuromuscular function is essential.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','hard','mcq','What is the mechanism by which magnesium sulphate prevents eclamptic seizures?','["A. GABA-A receptor potentiation, similar to benzodiazepines","B. Sodium channel blockade preventing action potential propagation","C. NMDA receptor antagonism, reducing cerebral vasospasm and neuronal excitability","D. Inhibition of cortical spreading depression via COX-2 inhibition"]','C','Magnesium is thought to prevent eclamptic seizures primarily through NMDA receptor antagonism — blocking glutamate-mediated excitatory neurotransmission, reducing neuronal hyperexcitability. It also reduces cerebral vasospasm by blocking calcium-dependent vasoconstriction. Unlike benzodiazepines, it does not cause maternal or fetal CNS depression at therapeutic doses.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','medium','mcq','Which antihypertensive used in pre-eclampsia acts by blocking alpha-1 and non-selective beta receptors?','["A. Nifedipine", "B. Methyldopa", "C. Labetalol", "D. Hydralazine"]','C','Labetalol is a combined alpha-1 and non-selective beta-blocker (alpha:beta blocking ratio approximately 1:3 oral, 1:7 IV). Alpha-1 blockade reduces peripheral vascular resistance; beta blockade reduces heart rate and cardiac output. It is a first-line choice for acute hypertension in pre-eclampsia.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','easy','mcq','Methyldopa is sometimes used as a long-term antihypertensive in pregnancy. What is its mechanism of action?','["A. Calcium channel blockade in vascular smooth muscle", "B. Direct arteriolar vasodilator", "C. Central alpha-2 agonist \u2014 reduces sympathetic outflow from the CNS", "D. ACE inhibitor reducing angiotensin II formation"]','C','Methyldopa is a prodrug converted to alpha-methylnoradrenaline in the CNS, which acts as an alpha-2 agonist. This reduces central sympathetic outflow, decreasing peripheral vascular resistance and blood pressure. It has a long safety record in pregnancy, though it can cause maternal sedation and depression.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','hard','mcq','A woman with severe pre-eclampsia at 28 weeks is given IV hydralazine for blood pressure control. She develops tachycardia and facial flushing. What is the mechanism of these side effects?','["A. Excessive alpha-1 blockade causing peripheral vasodilation", "B. Histamine release from mast cells causing flushing", "C. Reflex tachycardia due to direct arteriolar vasodilation and baroreflex activation", "D. Hydralazine-induced hypoglycaemia stimulating catecholamine release"]','C','Hydralazine is a direct arteriolar vasodilator (precise mechanism unclear, possibly involving cGMP). It causes reflex sympathetic activation via baroreceptors, resulting in tachycardia, increased cardiac output, and fluid retention. Flushing occurs from direct arteriolar dilation. These side effects limit its use, and it is now generally second/third line.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','hard','mcq','A woman develops severe pre-eclampsia with HELLP syndrome. Which of the following is the definitive treatment?','["A. High-dose corticosteroids to resolve haemolysis", "B. Plasma exchange to remove antibodies causing haemolysis", "C. Delivery of the fetus and placenta", "D. IV immunoglobulin to reduce platelet destruction"]','C','The definitive treatment of pre-eclampsia and HELLP syndrome (Haemolysis, Elevated Liver enzymes, Low Platelets) is delivery of the fetus and placenta. The placenta is the source of the antiangiogenic factors (sFlt-1, sEng) that cause the disease. Medical management stabilises the mother but does not cure the condition.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Pre-eclampsia Management','medium','mcq','A magnesium sulphate infusion is being monitored. Which parameter is the most reliable clinical indicator of toxicity?','["A. Serum potassium level","B. Urine output (should be >25 mL/hour)","C. Deep tendon reflexes (patellar reflex)","D. Pulse oximetry"]','C','Loss of deep tendon reflexes (specifically the patellar/knee jerk) is the earliest clinical sign of magnesium sulphate toxicity and precedes respiratory depression. The patellar reflex disappears at plasma magnesium levels of approximately 5-7 mmol/L (therapeutic range is 2-4 mmol/L). Regular reflex checks are mandatory during infusion.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','easy','mcq','Clomiphene citrate is used to induce ovulation. What is its mechanism of action?','["A. Directly stimulates the ovary to produce follicles", "B. Inhibits prolactin secretion, restoring ovulation", "C. Competes with oestrogen at hypothalamic oestrogen receptors, increasing GnRH and gonadotrophin release", "D. Exogenous FSH replacement to drive follicle development"]','C','Clomiphene is a selective oestrogen receptor modulator (SERM) that acts as an oestrogen antagonist at hypothalamic receptors. By blocking the negative feedback of oestrogen, it increases GnRH pulse frequency, leading to increased FSH and LH release from the pituitary, stimulating follicular development and ovulation.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','easy','mcq','Which serious complication can result from ovarian stimulation with gonadotrophins in fertility treatment?','["A. Premature ovarian failure", "B. Polycystic ovary syndrome", "C. Ovarian hyperstimulation syndrome (OHSS)", "D. Ovarian torsion from enlarged corpus luteum"]','C','Ovarian hyperstimulation syndrome (OHSS) is a potentially life-threatening complication of gonadotrophin stimulation. It causes massive ovarian enlargement, ascites, pleural effusion, haemoconcentration, and thromboembolism. Severe OHSS requires hospitalisation. GnRH antagonist protocols and dopamine agonists (cabergoline) reduce the risk.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','medium','mcq','GnRH agonists (e.g., buserelin, leuprorelin) are used in IVF protocols. How do they paradoxically reduce gonadotrophin levels?','["A. They directly inhibit FSH and LH synthesis in the anterior pituitary", "B. They stimulate prolactin release, which inhibits GnRH", "C. Continuous (non-pulsatile) GnRH receptor stimulation causes receptor downregulation and desensitisation \u2014 medical castration", "D. They block pituitary GnRH receptors as competitive antagonists"]','C','GnRH is released in pulses; GnRH agonists, given continuously, produce sustained non-pulsatile receptor stimulation. Initially there is a ''flare'' of gonadotrophin release, but after 2-3 weeks, GnRH receptors downregulate and desensitise, dramatically reducing FSH and LH levels (medical hypophysectomy). This is exploited in IVF long protocols and in treating hormone-sensitive conditions.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','medium','mcq','Letrozole has been shown to be more effective than clomiphene for ovulation induction in women with PCOS. What class of drug is letrozole?','["A. Selective oestrogen receptor modulator (SERM)", "B. Dopamine agonist", "C. Aromatase inhibitor", "D. GnRH antagonist"]','C','Letrozole is an aromatase inhibitor (AI). By inhibiting aromatase (CYP19A1), it reduces conversion of androgens to oestrogens, lowering oestrogen levels and thus removing negative feedback on the hypothalamus/pituitary. This increases FSH secretion and drives follicular development. The PPCOSII trial showed letrozole superior to clomiphene in PCOS for live birth rates.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','medium','mcq','A woman with hyperprolactinaemia and anovulatory infertility is treated with bromocriptine. What is its mechanism?','["A. Competitive prolactin receptor antagonist in the ovary", "B. Oestrogen receptor modulator \u2014 restores hypothalamic GnRH pulsatility", "C. Dopamine D2 receptor agonist \u2014 inhibits prolactin secretion from lactotrophs", "D. GnRH agonist stimulating FSH release"]','C','Bromocriptine and cabergoline are ergot-derived dopamine D2 receptor agonists. Dopamine is the physiological inhibitor of prolactin secretion (prolactin inhibitory factor). By mimicking dopamine, these drugs suppress hyperprolactinaemia, restoring pulsatile GnRH secretion and normal ovulation. Cabergoline is preferred due to its longer half-life and better tolerability.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','hard','mcq','A woman undergoing IVF is at high risk of OHSS. Which medication can be given at egg collection to reduce OHSS risk when GnRH agonist trigger is not possible?','["A. Progesterone pessaries", "B. Low-dose hCG supplementation", "C. Cabergoline (dopamine agonist)", "D. GnRH antagonist (cetrorelix)"]','C','Cabergoline, a dopamine D2 agonist, reduces VEGF receptor-2 phosphorylation and vascular permeability, which is the primary mechanism of OHSS fluid shifts. Given around egg collection in high-risk patients, it significantly reduces the incidence of moderate-to-severe OHSS. It is particularly useful when GnRH agonist trigger for final oocyte maturation cannot be used.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','hard','mcq','GnRH antagonists (cetrorelix, ganirelix) are used in IVF protocols. How do they differ mechanistically from GnRH agonists?','["A. They selectively block FSH receptors, allowing LH to continue", "B. They stimulate pituitary desensitisation more rapidly than GnRH agonists", "C. They competitively and immediately block GnRH receptors, preventing the LH surge without an initial flare", "D. They are given via a different route (IV) compared to GnRH agonists (SC)"]','C','GnRH antagonists (cetrorelix, ganirelix) competitively and immediately block GnRH receptors on pituitary gonadotrophs, rapidly suppressing FSH and LH without the initial flare effect seen with GnRH agonists. This allows a shorter, more flexible protocol in IVF and avoids the hyperoestrogen flare.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','easy','mcq','Human chorionic gonadotrophin (hCG) is used in fertility treatments. What does it mimic physiologically?','["A. FSH \u2014 stimulating follicular development", "B. GnRH \u2014 stimulating pituitary gonadotrophin release", "C. LH \u2014 triggering final oocyte maturation and ovulation", "D. Progesterone \u2014 supporting the luteal phase"]','C','hCG has structural and functional similarity to LH (both share the same beta receptor). It is used to trigger final oocyte maturation and ovulation (the hCG trigger shot) in IVF protocols, mimicking the endogenous LH surge. It can also support the corpus luteum (luteal phase support).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','medium','mcq','Metformin is sometimes used as an adjunct in fertility treatment for women with PCOS. What is its primary mechanism relevant to fertility?','["A. Direct ovarian stimulation by mimicking FSH", "B. Prolactin inhibition restoring GnRH pulsatility", "C. Reduction of hyperinsulinaemia and insulin resistance, thereby reducing androgen production and improving menstrual regularity", "D. GnRH agonism at the hypothalamus"]','C','In PCOS, hyperinsulinaemia drives excess ovarian androgen production (via LH receptor sensitisation). Metformin, by reducing insulin resistance, lowers insulin and LH levels, reducing androgen production and restoring menstrual regularity and ovulation in some women. It is used as an adjunct, particularly to prevent OHSS in IVF.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Fertility Drugs','hard','mcq','A woman with WHO Group I anovulation (hypogonadotrophic hypogonadism) fails to respond to clomiphene. What is the next appropriate treatment?','["A. High-dose clomiphene 200 mg/day", "B. GnRH agonist to stimulate FSH release", "C. Exogenous gonadotrophins (FSH/LH) administered by injection", "D. Laparoscopic ovarian drilling"]','C','Women with WHO Group I anovulation have low FSH and LH; clomiphene requires an intact hypothalamic-pituitary-ovarian axis and is ineffective. Exogenous gonadotrophins (recombinant FSH or human menopausal gonadotrophin containing FSH+LH) are given by injection to directly stimulate follicular development, bypassing the hypothalamic-pituitary axis.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','easy','mcq','Hormone replacement therapy (HRT) for menopausal symptoms typically contains which hormones?','["A. Testosterone and DHEA", "B. Progesterone only in all women", "C. Oestrogen alone (if hysterectomy) or oestrogen plus progestogen (if intact uterus)", "D. Oestrogen and FSH"]','C','HRT replaces the oestrogen deficient after menopause. Women with an intact uterus must take combined oestrogen + progestogen HRT because oestrogen alone causes endometrial hyperplasia and increases endometrial cancer risk. Women who have had a hysterectomy can take oestrogen-only HRT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','easy','mcq','What is the primary indication for HRT?','["A. Prevention of osteoporosis in all postmenopausal women", "B. Reduction of cardiovascular risk in postmenopausal women", "C. Treatment of troublesome menopausal symptoms \u2014 vasomotor symptoms (hot flushes, night sweats)", "D. Prevention of dementia and cognitive decline"]','C','The primary indication for HRT is relief of troublesome menopausal symptoms, particularly vasomotor symptoms (hot flushes, night sweats), which significantly impair quality of life. Secondary benefits include prevention of osteoporosis, but HRT is not recommended solely for cardiovascular or cognitive benefits.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','medium','mcq','The WHI (Women''s Health Initiative) trial raised concerns about combined HRT. Which adverse outcomes were identified?','["A. Increased risk of cervical cancer and endometrial cancer", "B. Increased risk of ovarian cancer only", "C. Increased risk of breast cancer, VTE, stroke, and coronary heart disease in older women", "D. Increased risk of type 2 diabetes and metabolic syndrome"]','C','The WHI trial (2002) of conjugated equine oestrogen + medroxyprogesterone acetate in women aged 50-79 showed increased risks of breast cancer, VTE, stroke, and CHD (in older women >60 or >10 years post-menopause). These risks are lower with transdermal oestrogen and micronised progesterone, and in younger women starting HRT near menopause onset.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','medium','mcq','Why is transdermal oestrogen preferred over oral oestrogen for HRT in women at risk of VTE?','["A. Transdermal oestrogen has higher bioavailability and provides better symptom control", "B. Transdermal oestrogen does not require a progestogen component", "C. Oral oestrogen undergoes first-pass hepatic metabolism, increasing clotting factors; transdermal oestrogen avoids this", "D. Oral oestrogen is associated with a higher risk of breast cancer than transdermal"]','C','Oral oestrogen undergoes first-pass hepatic metabolism, stimulating hepatic synthesis of clotting factors (especially factor VII, X, and fibrinogen) and reducing protein C and S. This increases VTE risk 2-4-fold. Transdermal oestrogen bypasses hepatic first-pass, producing physiological blood levels without this prothrombotic effect, making it preferable in women with VTE risk factors.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','medium','mcq','Tibolone is a synthetic steroid used as an alternative to conventional HRT. Which best describes its pharmacological profile?','["A. Pure oestrogen receptor agonist with no progestogenic activity", "B. SERM with anti-oestrogenic effects on the breast and uterus", "C. Tissue-selective compound with oestrogenic, progestogenic, and weak androgenic activities", "D. GnRH agonist reducing endogenous sex hormone production"]','C','Tibolone is a synthetic steroid with mixed oestrogenic, progestogenic, and weak androgenic activity. Its tissue selectivity means it provides vasomotor symptom relief and bone protection while not stimulating the breast or endometrium significantly. It can improve libido (androgenic effect). It is not associated with the same breast stimulation as combined HRT.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','hard','mcq','A 52-year-old woman with a BRCA2 mutation has had a bilateral mastectomy and oophorectomy and now has severe menopausal symptoms. What is the most appropriate approach to HRT?','["A. HRT is absolutely contraindicated in all BRCA mutation carriers", "B. Only non-hormonal options (SSRIs, clonidine) should be used", "C. Combined HRT with micronised progesterone is mandatory to protect the endometrium", "D. Oestrogen-only HRT may be considered as her breast cancer risk is mitigated by mastectomy and she has no uterus"]','D','After bilateral mastectomy and oophorectomy, BRCA2 carriers have a dramatically reduced breast cancer risk. The uterus has also been removed (oophorectomy implies bilateral procedure, and bilateral salpingo-oophorectomy in context of BRCA often accompanies hysterectomy or risk-reducing surgery). Oestrogen-only HRT can be considered carefully; the absolute risks are small compared to the quality of life and bone/cardiovascular benefits of treating severe surgical menopause.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','hard','mcq','Why is progestogen added to HRT in women with an intact uterus?','["A. To improve the efficacy of oestrogen in reducing hot flushes", "B. To maintain regular withdrawal bleeds in all HRT users", "C. To reduce the risk of breast cancer associated with oestrogen-only HRT", "D. To prevent oestrogen-induced endometrial hyperplasia and endometrial cancer"]','D','Unopposed oestrogen causes endometrial proliferation, progressing to hyperplasia and potentially endometrial cancer with prolonged use. Adding a progestogen provides endometrial protection by opposing oestrogenic proliferative effects. Women who have had a hysterectomy do not need progestogen as they have no uterus.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','easy','mcq','Which of the following is a benefit of HRT with regard to musculoskeletal health?','["A. Reversal of established vertebral fractures", "B. Improvement of muscle strength by androgenic effects", "C. Prevention of rheumatoid arthritis by anti-inflammatory action", "D. Prevention of osteoporosis by maintaining bone mineral density"]','D','Oestrogen maintains bone mineral density by inhibiting osteoclast activity and reducing bone turnover. After menopause, falling oestrogen levels accelerate bone resorption, increasing fracture risk. HRT effectively prevents postmenopausal osteoporosis and reduces fracture risk, though it is not first-line therapy for this indication alone.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','hard','mcq','Raloxifene is a SERM used for osteoporosis prevention in postmenopausal women. Which statement best describes its tissue-selective profile?','["A. Agonist at oestrogen receptors in bone and breast; antagonist in the uterus", "B. Oestrogen antagonist at all sites, working as an antiandrogen", "C. Non-selective oestrogen agonist similar to estradiol", "D. Antagonist at oestrogen receptors in breast and uterus; agonist in bone and cardiovascular tissue"]','D','Raloxifene is an oestrogen receptor agonist in bone (maintaining BMD and reducing fracture risk) and an antagonist in breast tissue (reduces breast cancer risk by ~50%) and uterus (does not stimulate endometrium). Unlike tamoxifen, it does not increase endometrial cancer risk. It does not treat vasomotor symptoms (may worsen them) and increases VTE risk.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','HRT','medium','mcq','A 55-year-old woman on HRT develops heavy irregular vaginal bleeding. What is the most important immediate investigation?','["A. Serum LH and FSH to assess menopausal status", "B. Clotting screen to exclude coagulopathy", "C. Serum oestradiol to determine if HRT dose is too high", "D. Transvaginal ultrasound and endometrial biopsy to exclude endometrial hyperplasia or cancer"]','D','Abnormal uterine bleeding on HRT must always be investigated to exclude endometrial pathology, particularly endometrial hyperplasia or carcinoma. Transvaginal ultrasound assesses endometrial thickness; biopsy (Pipelle or hysteroscopy) provides histological diagnosis. Undiagnosed endometrial cancer is a risk of inadequate progestogen cover.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','easy','mcq','GnRH agonists (e.g., leuprorelin, buserelin) are used in the treatment of endometriosis. What is their effect on endometriotic deposits?','["A. They directly destroy endometriotic tissue by inducing apoptosis", "B. They stimulate immune-mediated clearance of endometriotic cells", "C. They block prostaglandin receptors in endometriotic tissue, reducing pain", "D. They create a hypoestrogenic environment causing endometriotic deposits to atrophy"]','D','GnRH agonists, by downregulating pituitary GnRH receptors, create a hypoestrogenic state (medical menopause). Endometriosis is an oestrogen-dependent condition; in the absence of oestrogen, endometriotic deposits regress and become inactive. This provides symptom relief. Treatment is limited to 6 months due to bone density loss from hypoestrogenism.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','mcq','Mifepristone (RU-486) is used for medical termination of pregnancy. What is its mechanism of action?','["A. Prostaglandin receptor agonist causing cervical ripening", "B. Direct fetal cardiotoxin causing fetal demise", "C. Oxytocin analogue stimulating uterine contractions", "D. Competitive progesterone receptor antagonist \u2014 blocks progesterone effects and sensitises the uterus to prostaglandins"]','D','Mifepristone is a competitive antagonist at progesterone receptors (and glucocorticoid receptors). Blocking progesterone removes its uterine quiescence effect, causing endometrial breakdown and sensitising the myometrium to prostaglandins. It is followed 24-48 hours later by misoprostol (PGE1) to complete uterine evacuation.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','mcq','Uterine fibroids causing menorrhagia are treated with ulipristal acetate (Esmya) in some cases. What is its mechanism?','["A. GnRH agonist causing medical menopause and fibroid shrinkage", "B. Aromatase inhibitor reducing local oestrogen production in fibroids", "C. Oestrogen antagonist reducing fibroid vascularisation", "D. Selective progesterone receptor modulator (SPRM) \u2014 antiproliferative effect on uterine smooth muscle cells"]','D','Ulipristal acetate (Esmya) is an SPRM that acts on progesterone receptors in the uterus. It has antiproliferative and pro-apoptotic effects on fibroid smooth muscle cells, causing fibroid regression and reducing menorrhagia. Unlike GnRH agonists, it does not cause hypoestrogenism and can be used for longer-term management, though liver toxicity concerns have restricted use.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','mcq','A 30-year-old woman with severe endometriosis is prescribed danazol. She develops acne, hirsutism, and weight gain. Why?','["A. Danazol is a selective oestrogen receptor agonist causing virilisation paradoxically", "B. These are oestrogen withdrawal symptoms, not androgen effects", "C. Danazol causes polycystic ovarian changes increasing androgen production", "D. Danazol is a synthetic androgen and inhibits gonadotrophins \u2014 androgenic side effects reflect its weak anabolic/androgenic activity"]','D','Danazol is a synthetic steroid with weak androgenic and anabolic activity that suppresses the hypothalamic-pituitary-ovarian axis, creating a hypoestrogenic state. Its androgenic side effects (acne, hirsutism, voice deepening, weight gain, clitoromegaly) limit its use. It has largely been replaced by GnRH agonists and progestogens for endometriosis.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','hard','mcq','Elagolix is a novel treatment for endometriosis. How does it differ from traditional GnRH agonists?','["A. It is a selective progesterone receptor modulator with anti-oestrogenic effects", "B. It is an injectable GnRH agonist with superior downregulation compared to leuprorelin", "C. It selectively blocks FSH receptors without affecting LH", "D. It is an oral GnRH antagonist providing immediate, dose-dependent FSH/LH suppression without an initial flare"]','D','Elagolix is an oral, non-peptide GnRH receptor antagonist. Unlike GnRH agonists (which require continuous stimulation to cause downregulation and have an initial flare), GnRH antagonists immediately and competitively block receptors, providing rapid, dose-dependent suppression of LH and FSH. The oral route and lack of flare are key advantages.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','mcq','The levonorgestrel IUS (Mirena) is used as a treatment for menorrhagia (heavy menstrual bleeding). What is its primary mechanism for reducing bleeding?','["A. Systemic suppression of ovulation reducing oestrogen levels and endometrial growth", "B. Anti-inflammatory effect on prostaglandin synthesis in the endometrium", "C. Physical barrier preventing menstrual flow from reaching the cervix", "D. Local progestogenic endometrial atrophy reducing monthly endometrial shedding"]','D','The LNG-IUS delivers levonorgestrel directly into the uterine cavity at high local concentrations, causing endometrial atrophy through progestogenic effects. This dramatically reduces menstrual blood loss (80% reduction) and often causes amenorrhoea. Systemic absorption is low, minimising systemic side effects.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','mcq','A 38-year-old woman with large symptomatic uterine fibroids is given a GnRH agonist before surgery. An important clinical observation is that fibroids may regrow after stopping treatment. Why?','["A. GnRH agonists permanently suppress fibroid IGF-1 receptors which recover over time", "B. Fibroid regrowth is due to rebound hyperprolactinaemia after GnRH agonist cessation", "C. GnRH agonists suppress progesterone receptors which slowly recover", "D. Fibroids are oestrogen-responsive; GnRH agonist-induced hypoestrogenism causes shrinkage, but fibroids regrow when oestrogen levels recover after stopping treatment"]','D','Uterine fibroids express oestrogen and progesterone receptors and are hormonally responsive. GnRH agonists create a hypoestrogenic state causing fibroid shrinkage (20-50% volume reduction). However, this effect is temporary; once the drug is stopped, oestrogen levels recover and fibroids regrow, often returning to pre-treatment size within months. Surgery or alternative treatments are usually needed definitively.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','mcq','Tranexamic acid is first-line pharmacological treatment for heavy menstrual bleeding (menorrhagia). When is it taken?','["A. Continuously throughout the month", "B. Starting one week before expected menstruation", "C. In the luteal phase (second half of the cycle)", "D. Only during menstruation (on the days of heaviest bleeding)"]','D','Tranexamic acid is an antifibrinolytic taken only during menstruation. Endometrial fibrinolysis contributes significantly to heavy menstrual blood loss; by inhibiting plasminogen activation, tranexamic acid reduces blood loss by 40-50%. It is taken for the days of heavy bleeding only, not throughout the cycle, reducing systemic exposure and side effects.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','mcq','A patient is undergoing medical termination of pregnancy at 9 weeks. After mifepristone, which prostaglandin is administered to complete the process?','["A. Dinoprostone (PGE2) by vaginal pessary", "B. Alprostadil (PGE1) by intravenous infusion", "C. Carboprost (PGF2-alpha) by intramuscular injection", "D. Misoprostol (PGE1 analogue) sublingually or vaginally"]','D','Misoprostol (a PGE1 analogue) is administered vaginally, sublingually, or buccally 24-48 hours after mifepristone. It causes cervical ripening and uterine contractions, completing the expulsion process. Misoprostol is preferred because it is heat-stable (important in low-resource settings), cheap, and can be self-administered by patients at home.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','mcq','Alpha-1 blockers (e.g., tamsulosin, alfuzosin) are used in benign prostatic hyperplasia (BPH). What is their mechanism of action?','["A. Inhibit DHT production by blocking 5-alpha reductase", "B. Block androgen receptors in prostatic cells", "C. Directly reduce prostate volume by antiproliferative effect", "D. Relax smooth muscle in the prostate and bladder neck by blocking alpha-1A adrenoceptors"]','D','Alpha-1A adrenoceptors are the dominant subtype in the prostate and bladder neck. Blocking them relaxes smooth muscle, reducing urethral resistance and improving urinary flow within 24-48 hours. Alpha-1 blockers do not reduce prostate volume. Tamsulosin is more uroselective (alpha-1A selective), reducing the risk of postural hypotension compared to alfuzosin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','mcq','Finasteride is used for BPH and male-pattern baldness. What enzyme does it inhibit?','["A. Aromatase (CYP19A1)", "B. Testosterone hydroxylase (CYP17A1)", "C. 17-alpha hydroxylase", "D. 5-alpha reductase type II"]','D','Finasteride is a competitive inhibitor of 5-alpha reductase type II, the enzyme that converts testosterone to dihydrotestosterone (DHT) — the more potent androgen responsible for prostate growth and androgenic alopecia. Blocking DHT production reduces prostate volume (up to 25%) over 3-6 months and slows hair loss.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','mcq','A man with metastatic prostate cancer is started on leuprorelin (GnRH agonist). He is warned about a ''flare'' phenomenon. What causes this?','["A. Leuprorelin directly stimulates androgen receptors in prostate cancer cells", "B. The flare is caused by agonist antibody formation within the first month", "C. Leuprorelin inhibits prolactin causing a testosterone surge", "D. Initial GnRH receptor stimulation causes a transient LH surge, briefly increasing testosterone \u2014 potentially stimulating tumour growth"]','D','When GnRH agonists are first initiated, there is a transient surge (flare) in LH and FSH over 1-2 weeks, causing a transient rise in testosterone levels. This can paradoxically stimulate prostate cancer growth, causing ''flare'' — worsening bone pain, urinary retention, or spinal cord compression in metastatic disease. An anti-androgen (e.g., bicalutamide) is given for the first 2-4 weeks to cover this flare.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','mcq','Bicalutamide is used in prostate cancer treatment. What is its mechanism?','["A. Inhibits 5-alpha reductase, reducing DHT production", "B. CYP17A1 inhibitor reducing adrenal and testicular androgen synthesis", "C. GnRH agonist causing pituitary desensitisation and testosterone suppression", "D. Competitive androgen receptor antagonist \u2014 blocks testosterone and DHT from stimulating prostate cancer cells"]','D','Bicalutamide is a non-steroidal competitive antagonist at androgen receptors (AR). It blocks testosterone and DHT from binding to AR in prostate cancer cells, inhibiting their proliferative stimulation. Unlike steroidal antiandrogens (e.g., cyproterone), it does not reduce testosterone levels and does not cause the same degree of libido loss.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','mcq','Abiraterone acetate is used in castration-resistant prostate cancer (CRPC). What is its mechanism?','["A. Androgen receptor antagonist with higher affinity than bicalutamide", "B. 5-alpha reductase type I inhibitor reducing intratumoral DHT", "C. GnRH antagonist causing immediate testosterone suppression", "D. Irreversible inhibitor of CYP17A1 (17-alpha hydroxylase/C17,20-lyase), blocking androgen synthesis in the testes, adrenals, and tumour cells"]','D','Abiraterone is a prodrug hydrolysed to abiraterone, an irreversible inhibitor of CYP17A1 (17-alpha hydroxylase/C17,20-lyase). This enzyme is critical for androgen synthesis in the testes, adrenal glands, and within prostate tumour cells. By blocking it at all sites, abiraterone reduces testosterone and DHT even in castration-resistant disease. Prednisolone is co-prescribed to prevent adrenal insufficiency from accumulated precursor steroids.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','mcq','A man with BPH is prescribed tamsulosin. He reports dizziness on standing. What is the mechanism of this side effect?','["A. Tamsulosin causes bradycardia by beta-1 blockade", "B. Tamsulosin causes hyponatraemia resulting in postural dizziness", "C. Tamsulosin crosses the blood-brain barrier causing central hypotension", "D. Alpha-1 blockade of peripheral vascular alpha-1B receptors causes vasodilation and orthostatic hypotension"]','D','Tamsulosin is primarily alpha-1A selective, but some alpha-1B blockade occurs in peripheral blood vessels, causing vasodilation and orthostatic hypotension — particularly with the first dose. Patients should be warned to rise slowly from sitting or lying. Tamsulosin is more uroselective than non-selective alpha-1 blockers (prazosin) but hypotension can still occur.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','mcq','Enzalutamide is a second-generation androgen receptor antagonist used in CRPC. How does it differ from bicalutamide?','["A. Enzalutamide inhibits CYP17A1 rather than the androgen receptor", "B. Enzalutamide also inhibits 5-alpha reductase, providing dual action", "C. Enzalutamide causes more hepatotoxicity than bicalutamide", "D. Enzalutamide has higher androgen receptor binding affinity, blocks nuclear translocation of AR, and prevents AR-DNA binding, overcoming bicalutamide resistance mechanisms"]','D','Enzalutamide is a second-generation AR antagonist with 5-8-fold higher AR binding affinity than bicalutamide. Crucially, it also inhibits AR nuclear translocation and AR-DNA binding/coactivator recruitment. These additional actions overcome the agonist switch that can occur with bicalutamide in AR-overexpressing CRPC cells. However, enzalutamide resistance also develops, often through AR splice variants (e.g., AR-V7).','universal',true,'{year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','mcq','Dutasteride differs from finasteride for BPH treatment in which important way?','["A. Dutasteride is more selective and only blocks 5-alpha reductase type I", "B. Dutasteride is an alpha-1 blocker, not a 5-alpha reductase inhibitor", "C. Dutasteride acts faster than finasteride, reducing prostate volume within 2 weeks", "D. Dutasteride inhibits both 5-alpha reductase type I and type II, producing greater DHT reduction"]','D','Finasteride selectively inhibits 5-alpha reductase type II (the predominant isoform in the prostate). Dutasteride is a dual inhibitor of both type I and type II isoforms, producing greater (>90%) suppression of DHT compared to finasteride (~70%). Both drugs take 3-6 months to produce clinical benefit.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','mcq','Degarelix is used in the management of prostate cancer. How does it differ from leuprorelin?','["A. Degarelix is a GnRH agonist with faster onset than leuprorelin", "B. Degarelix requires combination with bicalutamide to prevent testosterone flare, unlike leuprorelin which does not", "C. Degarelix is an androgen receptor antagonist not a GnRH analogue", "D. Degarelix is a GnRH receptor antagonist \u2014 immediately suppresses LH and testosterone without an initial testosterone flare"]','D','Degarelix is a GnRH receptor antagonist (like cetrorelix) that competitively and immediately blocks pituitary GnRH receptors. This produces rapid, sustained suppression of LH, FSH, and testosterone within days, without the initial testosterone flare seen with GnRH agonists like leuprorelin. It therefore does not require co-prescription of an anti-androgen at initiation.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Prostate and Androgen Pharmacology','medium','mcq','Which important sexual side effect is reported with 5-alpha reductase inhibitors (finasteride/dutasteride)?','["A. Priapism", "B. Urinary incontinence from detrusor overactivity", "C. Retrograde ejaculation (primary mechanism)", "D. Erectile dysfunction, decreased libido, and ejaculatory dysfunction"]','D','5-alpha reductase inhibitors reduce DHT levels, which plays a role in sexual function. Side effects include reduced libido, erectile dysfunction, and ejaculatory dysfunction in approximately 5-8% of men. These effects are usually reversible on stopping the drug, though post-finasteride syndrome (persistent sexual and neurological symptoms) has been reported. Retrograde ejaculation is more characteristic of alpha-1 blockers.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Tocolytics','medium','mcq','A woman is admitted at 30 weeks with preterm labour. Which drug should be given to prevent preterm labour AND reduce the risk of neonatal cerebral palsy?','["A. Atosiban \u2014 reduces uterine contractions and directly inhibits fetal NMDA receptors", "B. Betamethasone \u2014 suppresses contractions and promotes fetal lung maturity", "C. Nifedipine \u2014 provides both tocolysis and neuroprotection by blocking calcium channels", "D. Magnesium sulphate \u2014 delays labour and provides fetal neuroprotection"]','D','Magnesium sulphate serves two roles in preterm labour before 32 weeks: tocolysis (short-term delay of delivery) and fetal neuroprotection. The neuroprotective effect is mediated via NMDA receptor antagonism in the fetal brain, reducing excitotoxic injury. Betamethasone promotes lung maturity but has no tocolytic effect. Nifedipine provides tocolysis only.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Reproductive System & OB-GYN','Pharmacology','Drugs for Gynaecological Conditions','medium','mcq','A 40-year-old woman with symptomatic uterine fibroids and menorrhagia is awaiting surgery. Which drug is used as a pre-operative medical treatment to reduce fibroid volume and correct anaemia?','["A. Mifepristone 200 mg daily", "B. Clomiphene to stimulate LH suppression", "C. Combined oral contraceptive pill to suppress menstruation", "D. GnRH agonist (e.g., leuprorelin depot) for 3-6 months pre-operatively"]','D','GnRH agonists (leuprorelin, goserelin, buserelin) are used pre-operatively in symptomatic fibroid patients to: reduce fibroid volume (20-50%), reduce vascularity (less intraoperative bleeding), correct anaemia (by inducing amenorrhoea), and potentially convert open surgery to laparoscopic. Treatment is limited to 3-6 months as hypoestrogenism causes bone loss.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Pharmacology 7th Ed');
